    pub(crate) fn plan_quota(&self, plan: &str) -> PlanQuota {
        if let Some(c) = self.plan_cache.borrow().get(plan) {
            return c.clone();
        }
        let mut resolved: Vec<(String, String, String)> = Vec::new();
        for e in self.roster.entries.iter().filter(|e| e.plan == plan) {
